#!/bin/shset -eecho "Waiting for MySQL at $DB_HOST:$DB_PORT..."while ! nc -z "$DB_HOST" "$DB_PORT"; do  sleep 1doneecho "MySQL is up."python manage.py migrate --noinputpython manage.py collectstatic --noinput --clearpython manage.py seed_dataexec gunicorn core.wsgi:application --bind 0.0.0.0:8000 --workers 3